Action: run_sql({'query': "SELECT \n    i.inspection_id,\n    i.inspection_date,\n    it.description as inspection_type,\n    i.inspection_score,\n    COUNT(v.violation_id) as total_violations,\n    COUNT(CASE WHEN vc.critical THEN 1 END) as critical_violations,\n    COUNT(CASE WHEN NOT vc.critical THEN 1 END) as noncritical_violations\nFROM inspections i\nJOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\nLEFT JOIN inspection_types it ON i.inspection_type_id = it.inspection_type_id\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE ek.slchd_establishment_key = 'STELLA GRILL|4291 S 900 E|MILLCREEK TS'\nGROUP BY i.inspection_id, i.inspection_date, it.description, i.inspection_score\nORDER BY i.inspection_date ASC;"})

